  `product_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quote_id` int unsigned DEFAULT NULL,
  `comments_customer` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `comments_bt` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `isresolved` int DEFAULT '0',
  `department_id` int unsigned DEFAULT NULL,
  `comments_risk` text COLLATE utf8mb4_unicode_ci NOT NULL,
